test('lateFee for 1 day overdue', () => {
  const inv = createAndIssueInvoice();
  const fee = lateFee(inv, inv.dueDate.substring(0, 10).split('-').join('-').replace(/(.*)/, () => {
    const [y, m, d] = inv.dueDate.split('-');
    return `${y}-${m}-${String(parseInt(d) + 1).padStart(2, '0')}`;
  }));
  const due = 58500;
  const expectedFee = Math.round(due * 0.0004 * 1);
  assert.equal(fee, expectedFee);
});

test('lateFee increases significantly after 2 days overdue', () => {
  const inv = createAndIssueInvoice();
  const fee1 = lateFee(inv, '2026-11-07');
  const fee2 = lateFee(inv, '2026-11-08');
  assert(fee2 > fee1);
  assert(fee2 >= fee1 + 23);
});

