test('dashboard mixed statuses', () => {
  const draft = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const issued = createAndIssueInvoice();
  let partial = createAndIssueInvoice('C-001');
  partial = recordPayment(partial, { amount: 20000, date: '2026-10-15' }).value;
  let paid = createAndIssueInvoice('C-002');
  paid = recordPayment(paid, { amount: 58500, date: '2026-10-15' }).value;

  const result = dashboard([draft, issued, partial, paid], '2026-11-15');
  assert.equal(result.value.counts.draft, 1);
  assert.equal(result.value.counts.issued, 1);
  assert.equal(result.value.counts.partially_paid, 1);
  assert.equal(result.value.counts.paid, 1);
});

test('dashboard contains all required fields', () => {
  const result = dashboard([], '2026-11-15');
